import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.BpFM782D.js";const p=JSON.parse('{"title":"requirement-analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"en/skills/requirement-analyzer.md","filePath":"en/skills/requirement-analyzer.md"}'),s={name:"en/skills/requirement-analyzer.md"};function r(o,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="requirement-analyzer" tabindex="-1">requirement-analyzer <a class="header-anchor" href="#requirement-analyzer" aria-label="Permalink to &quot;requirement-analyzer&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>requirement-analyzer</td></tr><tr><td>Description</td><td>Analyzes vague requirements into actionable frontend specs: feature breakdown, user flow, edge cases, accessibility audit, technical feasibility, and Go/No-Go decision. Use BEFORE writing code.</td></tr><tr><td>Source Directory</td><td><code>skills/requirement-analyzer/</code></td></tr></tbody></table><hr><h1 id="requirement-analyzer-1" tabindex="-1">Requirement Analyzer <a class="header-anchor" href="#requirement-analyzer-1" aria-label="Permalink to &quot;Requirement Analyzer&quot;">​</a></h1><p>Helps frontend engineers transform vague product requirements into actionable technical specifications.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ol><li><strong>Ask when uncertain, never fabricate</strong> — Avoid hallucination; better to ask one more round</li><li><strong>Read before asking</strong> — First gather context from project documents, then ask the user about what&#39;s missing</li><li><strong>Prefer existing technology</strong> — Use the project&#39;s current tech stack; only suggest alternatives when it cannot meet the need</li><li><strong>Edge Cases are the focus</strong> — Scan systematically to maximize problem discovery before development begins</li><li><strong>Output is connectable</strong> — Analysis results can feed directly into an OpenSpec change or feature-kickoff</li></ol><hr><h2 id="phase-0-context-collection-automatic" tabindex="-1">Phase 0: Context Collection (Automatic) <a class="header-anchor" href="#phase-0-context-collection-automatic" aria-label="Permalink to &quot;Phase 0: Context Collection (Automatic)&quot;">​</a></h2><p>After receiving a requirement, silently execute context collection — no extra action needed from the user.</p><h3 id="must-read" tabindex="-1">Must Read <a class="header-anchor" href="#must-read" aria-label="Permalink to &quot;Must Read&quot;">​</a></h3><ol><li><strong>CLAUDE.md</strong> — Get the tech stack, directory structure, and common commands</li><li><strong>Relevant .claude/rules/</strong> — Read corresponding rules based on the nature of the requirement: <ul><li>Involves UI → <code>design-rules.md</code></li><li>Involves API → <code>api-patterns.md</code></li><li>Involves routing/navigation → <code>ui-flows.md</code></li><li>Involves data → <code>content-model.md</code></li><li>Involves images → <code>image-assets.md</code></li></ul></li></ol><h3 id="read-as-needed" tabindex="-1">Read as Needed <a class="header-anchor" href="#read-as-needed" aria-label="Permalink to &quot;Read as Needed&quot;">​</a></h3><ol start="3"><li><strong>Relevant blueprint documents</strong> — If the requirement involves a specific domain: <ul><li>Page structure → <code>information-architecture/routes.md</code></li><li>Component specs → <code>design-system/components/frontstage/</code></li><li>Design mockup screenshots → <code>references/screenshots/</code></li></ul></li><li><strong>Existing code</strong> — Scan <code>src/</code> for similar features or reusable components</li><li><strong>Design mockup comparison</strong> — If the blueprint has related screenshots, compare the design against the current implementation and note unimplemented parts</li></ol><h3 id="context-summary" tabindex="-1">Context Summary <a class="header-anchor" href="#context-summary" aria-label="Permalink to &quot;Context Summary&quot;">​</a></h3><p>After collection, build an internal summary (not output to the user, but informs subsequent analysis):</p><ul><li><strong>Tech stack</strong>: From CLAUDE.md (framework, UI component library, data fetching approach, etc.)</li><li><strong>Project constraints</strong>: From rules (banned packages, rendering strategy, API format, etc.)</li><li><strong>Relevant existing code</strong>: Similar features and components that already exist</li><li><strong>Design guidelines</strong>: Color, typography, animation constraints, etc.</li></ul><hr><h2 id="phase-1-requirement-clarification-dialogue-phase" tabindex="-1">Phase 1: Requirement Clarification (Dialogue Phase) <a class="header-anchor" href="#phase-1-requirement-clarification-dialogue-phase" aria-label="Permalink to &quot;Phase 1: Requirement Clarification (Dialogue Phase)&quot;">​</a></h2><p><strong>This is the most critical phase and must be completed before proceeding.</strong></p><h3 id="accept-any-input-format" tabindex="-1">Accept Any Input Format <a class="header-anchor" href="#accept-any-input-format" aria-label="Permalink to &quot;Accept Any Input Format&quot;">​</a></h3><p>The user might provide:</p><ul><li>A one-line description (&quot;Build an events list page&quot;)</li><li>Screenshots or a Figma link</li><li>A spec document written by a PM</li><li>Conversational requirements (&quot;The homepage needs a popup ad&quot;)</li></ul><p>Regardless of format, digest it first, then start asking questions.</p><h3 id="questioning-flow" tabindex="-1">Questioning Flow <a class="header-anchor" href="#questioning-flow" aria-label="Permalink to &quot;Questioning Flow&quot;">​</a></h3><ol><li><strong>First round</strong> — Based on context collected in Phase 0, list all questions at once <ul><li>Do not re-ask things that can be inferred from project documents (e.g., API format, tech stack choices)</li><li>Focus on business decisions that project documents cannot answer</li></ul></li><li><strong>Follow-up</strong> — Based on user responses, continue asking about anything still unclear (may take multiple rounds)</li><li><strong>Confirm summary</strong> — After all questions are resolved, confirm understanding with a ✅ / ⚠️ list</li></ol><h3 id="question-directions-select-relevant-ones-based-on-the-requirement" tabindex="-1">Question Directions (select relevant ones based on the requirement) <a class="header-anchor" href="#question-directions-select-relevant-ones-based-on-the-requirement" aria-label="Permalink to &quot;Question Directions (select relevant ones based on the requirement)&quot;">​</a></h3><p><strong>Business Logic:</strong></p><ul><li>Who are the users of this feature? (eWill frontend is mostly anonymous visitors, but confirm if there are exceptions)</li><li>Where does the user go after completing the action? (refer to the 6 core flows in <code>ui-flows.md</code>)</li><li>Are there cross-page interactions? (e.g., homepage card → detail page)</li></ul><p><strong>Data:</strong></p><ul><li>Does the data come from an API or static content? (affects SSG vs SSR choice)</li><li>Are pagination or filtering needed?</li><li>Does it need real-time updates, or is latency acceptable?</li></ul><p><strong>Visual / Interaction:</strong></p><ul><li>Are there design mockups? (if so, read blueprint screenshots)</li><li>Are loading/error/empty states all needed?</li><li>Any animation requirements? (note the project bans <code>transition: all</code> and complex keyframes)</li></ul><p><strong>Edge Cases:</strong></p><ul><li>Ask in conjunction with the Edge Cases checklist (see <code>references/edge-cases-checklist.md</code>)</li><li>Ask about the 2–3 most likely boundary scenarios for the feature type</li></ul><hr><h2 id="phase-2-feature-breakdown" tabindex="-1">Phase 2: Feature Breakdown <a class="header-anchor" href="#phase-2-feature-breakdown" aria-label="Permalink to &quot;Phase 2: Feature Breakdown&quot;">​</a></h2><p><strong>Enter only after all questions are resolved.</strong></p><p>Break requirements down into deliverable, verifiable units of work.</p><h3 id="output-format" tabindex="-1">Output Format <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;Output Format&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Feature Point</th><th>Description</th><th>Acceptance Criteria</th><th>Priority</th></tr></thead><tbody><tr><td>FE-001</td><td>[Specific feature]</td><td>[What to do]</td><td>[How to define done]</td><td>P0/P1/P2</td></tr></tbody></table><h3 id="priority-definitions" tabindex="-1">Priority Definitions <a class="header-anchor" href="#priority-definitions" aria-label="Permalink to &quot;Priority Definitions&quot;">​</a></h3><ul><li><strong>P0</strong>: Core functionality; cannot launch without it</li><li><strong>P1</strong>: Important functionality; needed for v1</li><li><strong>P2</strong>: Nice-to-have; can iterate later</li></ul><h3 id="breakdown-principles" tabindex="-1">Breakdown Principles <a class="header-anchor" href="#breakdown-principles" aria-label="Permalink to &quot;Breakdown Principles&quot;">​</a></h3><ul><li>Each feature point should be small enough to develop and test independently (one PR granularity)</li><li>Acceptance criteria must be concrete and testable — avoid vague descriptions like &quot;works normally&quot;</li><li>If there are any assumptions, explicitly mark them as <code>⚠️ Assumption: ...</code></li><li>Map to the project&#39;s directory structure (which files need to be added/modified)</li></ul><hr><h2 id="phase-3-user-flow" tabindex="-1">Phase 3: User Flow <a class="header-anchor" href="#phase-3-user-flow" aria-label="Permalink to &quot;Phase 3: User Flow&quot;">​</a></h2><p>Draw the user operation flow using Mermaid syntax for readability.</p><h3 id="happy-path-main-flow" tabindex="-1">Happy Path (Main Flow) <a class="header-anchor" href="#happy-path-main-flow" aria-label="Permalink to &quot;Happy Path (Main Flow)&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[Start] --&amp;gt; B[Step 1] --&amp;gt; C[Step 2] --&amp;gt; D[End]</span></span></code></pre></div><h3 id="alternative-paths" tabindex="-1">Alternative Paths <a class="header-anchor" href="#alternative-paths" aria-label="Permalink to &quot;Alternative Paths&quot;">​</a></h3><p>List different scenarios with their trigger conditions.</p><h3 id="error-paths" tabindex="-1">Error Paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error Paths&quot;">​</a></h3><p>Each error path must include:</p><ul><li>Trigger condition (when does it occur)</li><li>What the user sees (error message, fallback page)</li><li>Recovery method (retry, go back, contact support)</li></ul><hr><h2 id="phase-4-edge-cases-accessibility" tabindex="-1">Phase 4: Edge Cases &amp; Accessibility <a class="header-anchor" href="#phase-4-edge-cases-accessibility" aria-label="Permalink to &quot;Phase 4: Edge Cases &amp; Accessibility&quot;">​</a></h2><p><strong>Systematically check boundary conditions — this is the core value of requirement-analyzer.</strong></p><p>When entering this phase, read <code>references/edge-cases-checklist.md</code> and select relevant dimensions based on the feature type.</p><h3 id="scan-logic" tabindex="-1">Scan Logic <a class="header-anchor" href="#scan-logic" aria-label="Permalink to &quot;Scan Logic&quot;">​</a></h3><p>Automatically select scan dimensions based on feature type:</p><table tabindex="0"><thead><tr><th>Feature Type</th><th>Primary Dimensions</th><th>Secondary Dimensions</th></tr></thead><tbody><tr><td>Form feature</td><td>Input boundary, network boundary</td><td>State boundary</td></tr><tr><td>List/detail</td><td>Data boundary, SEO boundary</td><td>Device boundary</td></tr><tr><td>Navigation/routing</td><td>State boundary, device boundary</td><td>—</td></tr><tr><td>Interactive component</td><td>State boundary, device boundary</td><td>Input boundary</td></tr><tr><td>Static display</td><td>Device boundary, SEO boundary</td><td>—</td></tr></tbody></table><h3 id="output-format-1" tabindex="-1">Output Format <a class="header-anchor" href="#output-format-1" aria-label="Permalink to &quot;Output Format&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Severity</th><th>Expected Behavior</th><th>Handling</th></tr></thead><tbody><tr><td>[Edge case]</td><td>High/Med/Low</td><td>[What should happen]</td><td>[Technical solution]</td></tr></tbody></table><ul><li>Every edge case must have a handling approach — don&#39;t just list them</li><li>If the handling approach requires confirmation with PM, mark as <code>⚠️ Pending confirmation</code></li><li>Severity judgment: High = user gets stuck or sees an error; Med = poor experience but functional; Low = minor imperfection</li></ul><h3 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h3><p>eWill is a public corporate website, so basic accessibility compliance is required. Each analysis must cover at minimum:</p><ul><li><strong>Keyboard navigation</strong> — All interactive elements are reachable by Tab; Enter/Space triggers them</li><li><strong>Screen readers</strong> — Important content has semantic HTML (heading hierarchy, aria-label, alt text)</li><li><strong>Focus management</strong> — Focus trap when a modal opens; focus returns to the trigger element when closed</li><li><strong>Color contrast</strong> — Text/background contrast ratio ≥ 4.5:1 (WCAG AA)</li><li><strong>Dynamic content</strong> — Supports <code>prefers-reduced-motion</code> (already defined in project design-rules.md)</li></ul><p>For features that involve forms, additionally check:</p><ul><li>[ ] Labels are correctly associated with inputs (<code>htmlFor</code> / <code>aria-labelledby</code>)</li><li>[ ] Error messages are associated with fields (<code>aria-describedby</code>)</li><li>[ ] Form submission results have live region notifications (<code>aria-live</code>)</li></ul><hr><h2 id="phase-5-technical-approach" tabindex="-1">Phase 5: Technical Approach <a class="header-anchor" href="#phase-5-technical-approach" aria-label="Permalink to &quot;Phase 5: Technical Approach&quot;">​</a></h2><p>Assess technical feasibility and suggest implementation directions. Skip time estimation (AI time estimates are unreliable); instead, assess complexity level.</p><h3 id="output-content" tabindex="-1">Output Content <a class="header-anchor" href="#output-content" aria-label="Permalink to &quot;Output Content&quot;">​</a></h3><p><strong>Technical Feasibility:</strong></p><ul><li>Is it feasible with the existing tech stack: ✅ Feasible / ⚠️ Challenging / ❌ Needs alternative</li><li>If there are challenges, describe them specifically</li></ul><p><strong>Rendering Strategy:</strong></p><ul><li>Suggest SSG or SSR based on requirement characteristics (refer to judgment criteria in tech-stack.md)</li></ul><p><strong>Component Structure Suggestion:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├── app/[route]/        # Page route</span></span>
<span class="line"><span>│   └── page.tsx</span></span>
<span class="line"><span>├── components/</span></span>
<span class="line"><span>│   └── sections/       # Page section components</span></span>
<span class="line"><span>│       └── [Feature]/</span></span>
<span class="line"><span>│           ├── index.tsx</span></span>
<span class="line"><span>│           └── [SubComponent].tsx</span></span>
<span class="line"><span>└── lib/                # Utility functions (if needed)</span></span></code></pre></div><p><strong>Dependencies:</strong></p><ul><li>Required API endpoints (cross-reference the endpoint list in <code>api-patterns.md</code>)</li><li>Other features that must be completed first</li><li>Required shared components (cross-reference existing <code>src/components/</code>)</li></ul><p><strong>Complexity Assessment:</strong></p><table tabindex="0"><thead><tr><th>Level</th><th>Description</th><th>Signals</th></tr></thead><tbody><tr><td>🟢 Low</td><td>Precedent exists; pure UI or simple API integration</td><td>1–2 components, no complex state</td></tr><tr><td>🟡 Medium</td><td>Requires new components or moderate state management</td><td>3–5 components, conditional rendering logic</td></tr><tr><td>🔴 High</td><td>Involves new architectural patterns or complex interactions</td><td>Cross-page state, real-time sync, third-party integration</td></tr></tbody></table><hr><h2 id="after-analysis" tabindex="-1">After Analysis <a class="header-anchor" href="#after-analysis" aria-label="Permalink to &quot;After Analysis&quot;">​</a></h2><h3 id="pending-items-summary" tabindex="-1">Pending Items Summary <a class="header-anchor" href="#pending-items-summary" aria-label="Permalink to &quot;Pending Items Summary&quot;">​</a></h3><p>Compile all <code>⚠️ Assumption</code> and <code>⚠️ Pending confirmation</code> items at the bottom of the document:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Pending Items</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| # | Item | Impact Scope | Default Handling |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|------|-------------|-----------------|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 1 | [Pending content] | [Which feature points are affected] | [Default approach if not confirmed] |</span></span></code></pre></div><h3 id="go-no-go-feasibility-decision" tabindex="-1">Go/No-Go Feasibility Decision <a class="header-anchor" href="#go-no-go-feasibility-decision" aria-label="Permalink to &quot;Go/No-Go Feasibility Decision&quot;">​</a></h3><p>Based on the analysis results, provide a clear feasibility judgment:</p><table tabindex="0"><thead><tr><th>Decision</th><th>Condition</th><th>Description</th></tr></thead><tbody><tr><td>✅ <strong>GO</strong></td><td>Requirements are clear, technically feasible, no High pending items</td><td>Can proceed directly to development</td></tr><tr><td>⚠️ <strong>CONDITIONAL GO</strong></td><td>Mostly feasible, but 1–2 items need PM confirmation</td><td>List blocking items; development can start after confirmation</td></tr><tr><td>❌ <strong>NO-GO</strong></td><td>Requirements severely insufficient, technically infeasible, or multiple High pending items</td><td>Explain blockers; suggest next steps</td></tr></tbody></table><p>Considerations:</p><ul><li>Number and severity of pending items</li><li>Whether the tech stack supports the requirement</li><li>Whether required API or backend dependencies are ready</li><li>Whether High-severity edge cases have clear handling plans</li></ul><h3 id="connecting-to-next-steps" tabindex="-1">Connecting to Next Steps <a class="header-anchor" href="#connecting-to-next-steps" aria-label="Permalink to &quot;Connecting to Next Steps&quot;">​</a></h3><p>After analysis, provide connection options:</p><ol><li><strong>Produce Markdown document</strong> — Save as <code>docs/requirements/[feature-name].md</code></li><li><strong>Connect to OpenSpec</strong> — Use the analysis results as input for <code>/opsx:new</code> or <code>/opsx:ff</code></li><li><strong>Connect to feature-kickoff</strong> — Proceed directly to the development startup workflow</li><li><strong>View a specific phase</strong> — Output results for a specific Phase only</li></ol><p>Full conversation examples and output formats are in <code>references/examples.md</code>.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Do not introduce packages banned by the project in the analysis (e.g., axios, lodash, Vitest)</li><li>API format: standardized POST + RPC style (refer to api-patterns.md)</li><li>Colors/fonts/border-radius etc. must follow design-rules.md</li><li>If the requirement is outside the frontend scope (requires backend support), explicitly note &quot;Backend support required&quot;</li></ul>`,101)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
